import{z as s,x as l,o as t,c as d,q as B,j as i,D as e,d as A,s as o,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"分布式事务案例与收束","description":"","frontmatter":{"title":"分布式事务案例与收束","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dt-case-map.md","filePath":"cs/dt-case-map.md","lastUpdated":1791063341000}'),p={name:"cs/dt-case-map.md"};function m(C,a,D,F,c,u){const r=l("Mermaid");return t(),d("div",null,[a[2]||(a[2]=B('<h1 id="分布式事务案例与收束" tabindex="-1">分布式事务案例与收束 <a class="header-anchor" href="#分布式事务案例与收束" aria-label="Permalink to &quot;分布式事务案例与收束&quot;">​</a></h1><div class="epigraph"><p>分布式事务最好的优化常常不是更聪明的协议，而是更少的跨片事务：把数据搬到事务需要在的地方。</p><footer>—— 据 Gray and Reuter, Transaction Processing, 1993；本课程六课的协议与体系账</footer></div><p><a href="/cs/dt-isolation-implementation">上一课</a>把隔离钉在时间戳与提交点校验上。本课程到此收束：先用三份案例把六课的清单走一遍，再给出「要不要跨片事务」的决策口径。协议课（2PC 实现、Percolator 与 TiDB、Calvin）与体系课（谱系、隔离实现）在此拼成一张部署图。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>协议都会背，案例里难的从来是选择：哪些操作必须原子，哪些补偿就能过。缺口是<strong>把协议选择翻译回业务约束</strong>：一笔转账要跨片原子；一天一次的对账报表不必；购物车合并不需要快照隔离，库存扣减需要。这一步翻译错一行，选型全错。最常见的错法有两个：把所有跨服务调用都包进「分布式事务」，以及反过来，该原子的地方用重试凑——前者把协议税加在不需要的账上，后者把撕票的风险留给生产环境夜里爆发。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>案例 A，TiDB 一类：账务负载走悲观模式加 Percolator 主锁，TSO 批量发号；设计分片键把扣减与流水放进同一分片，2PC 退化成单片事务——最好的一次优化是不跨片。案例 B，Spanner 一类：全球一致性场景老实付 commit wait 与跨组 2PC 的税，读走快照时间戳，热点账户按子键拆分避免长锁；隔离档位按上一课的三段账显式声明，不靠默认值。反例 C：把下单、扣库存、调支付三个跨服务步骤包进 2PC 的尝试——正确答案是幂等加重试加补偿（Saga），不是提交协议；<a href="/cs/consensus-vs-2pc">共识与 2PC</a> 的老口径在这里兑现：原子提交协议管的是存储层同归同败，不管业务补偿的先后与可审计。运维清单四件：挂着不放的 in-doubt 事务要告警；TSO 或发号器要可扩容、可恢复；时钟漂移要监控（TrueTime 系这是生命线）；隔离级别要用一致性测试抽查，而不是信任文档。</p><p><span class="marginnote">把跨服务调用误包进 2PC 的典型结局：数据库都已 prepared、锁挂着，第三方接口却超时了。协议没有错，是用错了层——业务步骤没有「prepared 后必达」的性质，撑不起这份合同。</span></p><p><span class="marginnote">in-doubt（悬而未决）事务：协调者已让所有参与者 prepared，却还没来得及宣布提交或回滚——最常见于协调者恰好崩溃的瞬间。此时这些行上的锁全被攥着，别的业务碰到只能排队。运维清单把「挂着不放的 in-doubt」列为头号告警，就是因为它一出现，整片数据开始变慢。</span></p>',9)),(t(),i(n,null,{default:e(()=>[o(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E4%B8%8B%E5%8D%95%20%E2%86%92%20%E6%89%A3%E5%BA%93%E5%AD%98%20%E2%86%92%20%E8%B0%83%E6%94%AF%E4%BB%98%22%5D%20--%3E%20F%5B%22%E7%AC%AC%E4%B8%89%E6%AD%A5%E8%B6%85%E6%97%B6%E5%A4%B1%E8%B4%A5%22%5D%0A%20%20F%20--%3E%20PC%5B%222PC%20%E8%B7%AF%E7%BA%BF%EF%BC%9A%E5%89%8D%E4%B8%A4%E6%AD%A5%E5%B7%B2%20prepared%EF%BC%8C%E9%94%81%E6%8C%82%E7%9D%80%E4%B8%8D%E6%94%BE%22%5D%20--%3E%20ID%5B%22in-doubt%20%E5%A0%86%E7%A7%AF%EF%BC%8C%E5%90%8E%E7%BB%AD%E4%B8%9A%E5%8A%A1%E5%85%A8%E8%A2%AB%E6%8B%96%E6%AD%BB%22%5D%0A%20%20F%20--%3E%20SG%5B%22Saga%20%E8%B7%AF%E7%BA%BF%EF%BC%9A%E6%B2%BF%E6%97%A5%E5%BF%97%E9%80%86%E5%90%91%E8%A1%A5%E5%81%BF%22%5D%20--%3E%20CM%5B%22%E9%80%80%E5%BA%93%E5%AD%98%E3%80%81%E6%92%A4%E8%AE%A2%E5%8D%95%EF%BC%8C%E6%AF%8F%E6%AD%A5%E5%B9%82%E7%AD%89%E3%80%81%E5%8F%AF%E5%AE%A1%E8%AE%A1%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[A("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"决策口径三问。一问：事务能不能单片？能，就改分片键，任何协议税都省了。二问：失败时补偿是否可行且可审计？可行，用 Saga——每步幂等，失败沿日志逆向补偿；不可行（钱已出账、货已发出），才动原子提交。三问：读要不要新鲜到外部一致？要，付 commit wait 或选严格串行实现；不要，快照加会话戳足够。性能账从第一课继承：税 = 锁持有时间 × 分片数 × 消息轮次，后面每一课的优化各砍一项——async commit 砍轮次，定序免对话，commit wait 用等待换序，单片化直接把乘数清零。没有免费的一项；声称免费的那一项，多半是被挪到了别人头上。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"给性能税代个数：锁持有 5 毫秒 × 2 个分片 × 4 轮消息，按这个乘法粗算就是 40 毫秒量级的协调开销；分片数或轮次翻倍，税跟着翻倍。这也解释了为什么 async commit 砍轮次的收益常常比苦磨锁本身更大——轮次往往是乘法里最大的因子。")],-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"初学者容易以为隔离级别默认就是对的。实际上多数数据库默认只给到读已提交或快照，文档里写「可串行化」的有的只是近似实现；所以清单要求用一致性测试实测抽查，而不是信任名字——选型错档位的故障，往往要到并发上来之后才爆发。")],-1)),(t(),i(n,null,{default:e(()=>[o(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q1%7B%22%E4%BA%8B%E5%8A%A1%E8%83%BD%E5%8D%95%E7%89%87%EF%BC%9F%22%7D%20--%3E%7C%E8%83%BD%7C%20SH%5B%22%E6%94%B9%E5%88%86%E7%89%87%E9%94%AE%EF%BC%8C%E9%80%80%E5%8C%96%E4%B8%BA%E5%8D%95%E7%89%87%E4%BA%8B%E5%8A%A1%22%5D%0A%20%20Q1%20--%3E%7C%E4%B8%8D%E8%83%BD%7C%20Q2%7B%22%E8%A1%A5%E5%81%BF%E5%8F%AF%E8%A1%8C%E4%B8%94%E5%8F%AF%E5%AE%A1%E8%AE%A1%EF%BC%9F%22%7D%0A%20%20Q2%20--%3E%7C%E6%98%AF%7C%20SG%5B%22%E5%B9%82%E7%AD%89%20%2B%20%E9%87%8D%E8%AF%95%20%2B%20Saga%20%E8%A1%A5%E5%81%BF%22%5D%0A%20%20Q2%20--%3E%7C%E5%90%A6%7C%20Q3%7B%22%E8%AF%BB%E8%A6%81%E5%A4%96%E9%83%A8%E4%B8%80%E8%87%B4%EF%BC%9F%22%7D%0A%20%20Q3%20--%3E%7C%E8%A6%81%7C%20ST%5B%22%E5%8E%9F%E5%AD%90%E6%8F%90%E4%BA%A4%20%2B%20commit%20wait%22%5D%0A%20%20Q3%20--%3E%7C%E4%B8%8D%E8%A6%81%7C%20SIS%5B%22%E5%BF%AB%E7%85%A7%20%2B%20%E4%BC%9A%E8%AF%9D%E6%88%B3%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=B('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不排产品名次，不替业务宣布「正确级别」，也不展开队列削峰与最终一致的实现——那是流处理与系统模式的课。再往深走是各系统的论文与源码，不在本课程树内。六课的账各归各位：协议课管提交怎么不撕票，体系课管谱系怎么读，隔离课管级别怎么落地，本课管什么时候根本不该跨片。本课程到此收束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>选型第一问是「能不能单片」：分片键设计优于一切协议优化。</li><li>补偿可行用 Saga，不可行才动原子提交；提交协议不管业务补偿。</li><li>性能税 = 锁持有 × 分片数 × 轮次；各课优化各砍一项，没有免费的一项。</li><li>运维四件：in-doubt 告警、发号器扩容、时钟漂移监控、隔离级别抽查。</li><li>出处：Gray and Reuter 1993；Corbett et al. 2012；Thomson et al. 2012；Peng and Dabek 2010。本课程到此收束。</li></ul>',4))])}const T=s(p,[["render",m]]);export{S as __pageData,T as default};
